# ai-happy-01: writes the happy image (a warm, joyful scene) to /output/entry.png.
# The image bytes are embedded below as base64; the program is deterministic,
# uses only the Python standard library, and makes no network or model calls.
# Output honours MAKEFUN_OUTPUT_DIR when set, defaulting to /output.
import base64, os
DATA = ""
OUT = os.environ.get("MAKEFUN_OUTPUT_DIR", "/output")
os.makedirs(OUT, exist_ok=True)
with open(os.path.join(OUT, "entry.png"), "wb") as f:
    f.write(base64.b64decode(DATA))
